class Solution {public:int solve(vector<vector<int>>g){int m=g.size(),n=m?g[0].size():0;if(!n)return 0;vector<vector<int>>id(m,vector<int>(n,-1));vector<int>size;int dr[]={-1,1,0,0},dc[]={0,0,-1,1},best=0;for(int r=0;r<m;r++)for(int c=0;c<n;c++)if(g[r][c]&&id[r][c]<0){int label=size.size();vector<pair<int,int>>q{{r,c}};id[r][c]=label;for(int i=0;i<(int)q.size();i++)for(int k=0;k<4;k++){int x=q[i].first+dr[k],y=q[i].second+dc[k];if(x>=0&&x<m&&y>=0&&y<n&&g[x][y]&&id[x][y]<0){id[x][y]=label;q.push_back({x,y});}}size.push_back(q.size());best=max(best,(int)q.size());}for(int r=0;r<m;r++)for(int c=0;c<n;c++)if(!g[r][c]){set<int>near;for(int k=0;k<4;k++){int x=r+dr[k],y=c+dc[k];if(x>=0&&x<m&&y>=0&&y<n&&id[x][y]>=0)near.insert(id[x][y]);}int value=1;for(int label:near)value+=size[label];best=max(best,value);}return best;}};